package com.primehr.rsp.evaluation.infrastructure;
import com.primehr.rsp.evaluation.domain.EvaluationProceeding; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface EvaluationProceedingRepository extends JpaRepository<EvaluationProceeding,String>{Optional<EvaluationProceeding> findByIdAndAgencyId(String id,String agency);boolean existsByAgencyIdAndCurrentPublicationKey(String agency,String publication);List<EvaluationProceeding>findByAgencyIdAndPublicationIdOrderByCreatedAtDesc(String agency,String publication);@Query("select p from EvaluationProceeding p where p.agencyId=:agency and (:admin=true or exists(select m.id from CommitteeMember m where m.agencyId=:agency and m.committeeId=p.committee.id and upper(m.employeeNo)=upper(:actor) and m.effectiveFrom<=p.plannedAsOfDate and (m.effectiveTo is null or m.effectiveTo>=p.plannedAsOfDate)))") Page<EvaluationProceeding> findPermitted(@Param("agency")String agency,@Param("actor")String actor,@Param("admin")boolean admin,Pageable pageable);}
